const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const southeastPoint = ee.Geometry.Point([121.96499287870442, 24.83594812988359]);
  const northwestPoint = ee.Geometry.Point([121.93452298429524, 24.84607374884142]);
  const date = '2021-09-29';

  // 2. Data Acquisition - Sentinel-2 L2A for accurate color
  const s2Col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate('2021-09-28', '2021-09-30')
    .filterBounds(ee.Geometry.MultiPoint([southeastPoint, northwestPoint]))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 30));

  const s2ColSize = s2Col.size().getInfo();
  console.log(`Sentinel-2 images: ${s2ColSize}`);

  if (s2ColSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get least cloudy image
  const image = s2Col.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 3. Processing - Focus on blue band (B2) for color analysis
  const blueBand = 'B2';

  // Sample both points
  const seSample = image.select(blueBand).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southeastPoint.buffer(30),
    scale: 10,
    maxPixels: 1e9
  });

  const nwSample = image.select(blueBand).reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northwestPoint.buffer(30),
    scale: 10,
    maxPixels: 1e9
  });

  const seValue = seSample.get(blueBand).getInfo();
  const nwValue = nwSample.get(blueBand).getInfo();

  console.log(`SE Blue Reflectance: ${seValue ? seValue.toFixed(4) : 'No data'}`);
  console.log(`NW Blue Reflectance: ${nwValue ? nwValue.toFixed(4) : 'No data'}`);

  // 4. Validation & Final Answer
  if (seValue === null || nwValue === null) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (isNaN(seValue) || isNaN(nwValue) || seValue < 0 || seValue > 1 || nwValue < 0 || nwValue > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Higher blue reflectance = lighter blue color
  if (seValue > nwValue) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
